9. 			progressMonitor.setFileName(fileHeader.getFileName());
10. 			
11. 			if (!outPath.endsWith(InternalZipConstants.FILE_SEPARATOR)) {
12. 				outPath += InternalZipConstants.FILE_SEPARATOR;
13. 			}
14. 
15. 			
16. 			String fileName = fileHeader.getFileName();
17. 			String completePath = outPath + fileName;
18. 			if (!new File(completePath).getCanonicalPath().startsWith(new File(outPath).getCanonicalPath())) {
19. 				throw new ZipException(
20. 						"illegal file name that breaks out of the target directory: " + fileHeader.getFileName());
21. 			}
22. 
23. 			
24. 			
25. 			if (fileHeader.isDirectory()) {
26. 				try {
27. 					if (!Zip4jUtil.isStringNotNullAndNotEmpty(fileName)) {
28. 						return;
29. 					}
30. 					File file = new File(completePath);
31. 					if (!file.exists()) {
32. 						file.mkdirs();
33. 					}
34. 				} catch (Exception e) {
35. 					progressMonitor.endProgressMonitorError(e);
36. 					throw new ZipException(e);
37. 				}
38. 			} else {
39. 				
40. 				checkOutputDirectoryStructure(fileHeader, outPath, newFileName);
41. 				
42. 				UnzipEngine unzipEngine = new UnzipEngine(zipModel, fileHeader);
43. 				try {
44. 					unzipEngine.unzipFile(progressMonitor, outPath, newFileName, unzipParameters);
45. 				} catch (Exception e) {
46. 					progressMonitor.endProgressMonitorError(e);
47. 					throw new ZipException(e);
48. 				}
49. 			}
50. 		} catch (ZipException e) {
51. 			progressMonitor.endProgressMonitorError(e);
52. 			throw e;
53. 		} catch (Exception e) {
54. 			progressMonitor.endProgressMonitorError(e);
55. 			throw new ZipException(e);
56. 		}
57. 	}
